// A workflow GitHub refuses to run for ci_before, the tool that runs the fast CI on the tests alone on the code before
// the change, is what it is for measure: a refusal its engineer reads, not a failed tool of a kind the flow does not
// name, tried three times. Its reference is the contract of the failure kind `rejected` (it is "never given as a failed
// tool") and the kinds of failure the flow's cell X1 lists.
#[test]
fn a_dispatch_github_refuses_for_ci_before_is_a_refusal_and_not_a_failed_tool() {
    let s = setup("ci-before-rejected");
    let project = std::fs::read_to_string(s.data.join("projects/p.toml")).unwrap();
    write(
        &s.data,
        "projects/p.toml",
        &format!("{project}tests_input = \"command\"\n"),
    );
    git(&s.data, &["commit", "-q", "-am", "the fast CI takes the tests it runs"]);
    let mut agents = scripts();
    agents.insert(
        "I1",
        Box::new(|r: &Request, _: usize| {
            let wt = &r.worktree;
            write(wt, "src/lib.txt", "old\nfeature\n");
            write(wt, "tests/feature.txt", "feature\n");
            git(wt, &["add", "-A"]);
            git(wt, &["commit", "-q", "-m", "Add the feature"]);
            let head = git(wt, &["rev-parse", "HEAD"]);
            let tools = json!([
                { "tool": "ci", "head": head, "tests": ["feature"], "pr": { "title": "Add the feature", "body": "It adds it." } },
                { "tool": "ci_before", "head": head, "files": ["tests/feature.txt"], "tests": ["reject"] },
            ]);
            (vec![("outcome", "tools")], vec![("outcome.tools", tools)])
        }),
    );
    let (mut e, said, item) = start(&s, agents);
    step_to(&mut e, item, "X1");
    e.step(None).unwrap();
    let log = said.lock().unwrap().join("\n");
    let runs = tool_runs(&e, item, "ci_before");
    let listed = [
        "network_or_api",
        "ci_did_not_start",
        "timed_out",
        "machine_down",
        "other",
    ];
    for r in &runs {
        if let Some(kind) = r.1["failed"]["kind"].as_str() {
            assert!(
                listed.contains(&kind),
                "a failed tool of the kind {kind}, which the flow does not name: {runs:?}"
            );
        }
    }
    // Asked for once and not tried again, and the engineer is told what GitHub said.
    assert_eq!(runs.len(), 1, "{runs:?}\n{log}");
    assert_eq!(runs[0].1["ran"]["verdict"], "refused", "{runs:?}\n{log}");
    assert!(
        runs[0].1["ran"]["why"].as_str().is_some_and(|w| w.contains("HTTP 422")),
        "{runs:?}"
    );
    assert_eq!(s.by_hand.lock().unwrap().len(), 1);
    // The temporary branch of the tests is gone; the work's own branch, which ci pushed, may be there.
    let branches = remote_branches(&s);
    assert!(
        branches.iter().all(|b| !b.contains("wf-agents-before")),
        "{branches:?}\n{log}"
    );
    let _ = std::fs::remove_dir_all(&s.root);
}

// A project that lists no measurement workflow is told so, and what to answer instead; nothing runs, the request is a
// row of tool_runs but not a run of a measurement, so an answer of measured is sent back and one of not_measured stands.
#[test]
fn a_project_that_lists_no_measurement_workflow_is_told_to_answer_not_measured() {
    let s = setup("measure-none");
    let mut agents = scripts();
    agents.insert(
        "D2",
        Box::new(|r: &Request, n: usize| {
            let acceptance = json!([{ "by": "test", "id": "A1", "condition": "The feature is there." }]);
            match n {
                1 => {
                    let head = git(&r.worktree, &["rev-parse", "HEAD"]);
                    let tools = json!([measure_request(&head, "measure.yml", "command=true")]);
                    (vec![("outcome", "tools")], vec![("outcome.tools", tools)])
                }
                2 => (
                    vec![("outcome.measure", "measured")],
                    vec![("outcome.acceptance", acceptance)],
                ),
                _ => (
                    vec![("outcome.measure", "not_measured")],
                    vec![("outcome.acceptance", acceptance)],
                ),
            }
        }),
    );
    let (mut e, said, item) = start(&s, agents);
    for _ in 0..40 {
        if ended_at(&e, item, "D2").len() >= 3 {
            break;
        }
        e.step(None).unwrap();
    }
    let log = said.lock().unwrap().join("\n");
    let runs = tool_runs(&e, item, "measure");
    assert_eq!(runs.len(), 1, "{runs:?}\n{log}");
    assert_eq!(runs[0].1["push"]["verdict"], "refused", "{runs:?}");
    let why = runs[0].1["push"]["why"].as_str().unwrap();
    assert!(why.contains("ci.measure") && why.contains("not_measured"), "{why}");
    assert!(s.by_hand.lock().unwrap().is_empty());
    assert_eq!(remote_branches(&s), ["refs/heads/main"], "{log}");
    // The answer of measured is sent back, saying why; the answer of not_measured is taken.
    let d2 = ended_at(&e, item, "D2");
    assert_eq!(d2.len(), 3, "{d2:?}\n{log}");
    assert_eq!(d2[0], (Some("tools".to_string()), None), "{d2:?}");
    assert!(
        d2[1].0.is_none()
            && d2[1]
                .1
                .as_deref()
                .is_some_and(|why| why.contains("measured, but this work has no measure run")),
        "{d2:?}\n{log}"
    );
    assert!(d2[2].0.is_some() && d2[2].1.is_none(), "{d2:?}\n{log}");
    let _ = std::fs::remove_dir_all(&s.root);
}

/// The form of a tool in the schema of the common format, as an agent is given it: the object that holds its
/// properties.
fn tool_form(schema: &Value, tool: &str) -> Option<Value> {
    match schema {
        Value::Object(o) => {
            if o.get("properties")
                .and_then(|p| p.get("tool"))
                .is_some_and(|t| t["const"] == tool)
            {
                return Some(schema.clone());
            }
            o.values().find_map(|v| tool_form(v, tool))
        }
        Value::Array(xs) => xs.iter().find_map(|v| tool_form(v, tool)),
        _ => None,
    }
}

/// What each of the cells that ask for the tools is told of the gh tool and of the measure tool in the common format its
/// session is given for the project: the cell, the gh tool's description and the description of the measure tool's input
/// that names the workflow. The cells are the research (`R1`), the design (`D1`, `D2`) and the implementation (`I1`).
fn tool_descriptions(s: &Setup) -> Vec<(&'static str, String, String)> {
    let (e, _) = engine(s, scripts());
    let flow = e.flow(e.flow_now).unwrap();
    let g = flow.graphs.iter().find(|g| g.name == engine::ENGINEER).unwrap();
    ["R1", "D1", "D2", "I1"]
        .into_iter()
        .map(|cell| {
            let parts = engine::message::line_parts(&e, g, g.cell(cell).unwrap(), "p");
            let common = parts
                .iter()
                .find(|(address, _)| address == "format:common")
                .and_then(|(_, text)| text.as_str())
                .unwrap();
            // The schema is the last part of the text, which holds no blank line.
            let schema: Value = serde_json::from_str(common.rsplit("\n\n").next().unwrap()).unwrap();
            let gh = tool_form(&schema, "gh").unwrap_or_else(|| panic!("{cell}: no gh tool"));
            let measure = tool_form(&schema, "measure").unwrap_or_else(|| panic!("{cell}: no measure tool"));
            (
                cell,
                gh["properties"]["tool"]["description"].as_str().unwrap().to_string(),
                measure["properties"]["workflow"]["description"]
                    .as_str()
                    .unwrap()
                    .to_string(),
            )
        })
        .collect()
}

// What the cells that research, design and implement are told of the gh tool and of the measure tool holds the values
// of the settings they name, as the installation and the project set them now: the allow list of gh, and the
// workflows the project lists, which read as none where it lists none; a change of either shows in the description
// given next. A design that does not know the project lists no measurement workflow would lock acceptance conditions
// that need one.
#[test]
fn the_tools_are_described_with_the_settings_in_force() {
    let s = setup("tool-settings");
    let told = tool_descriptions(&s);
    assert_eq!(told.len(), 4);
    for (cell, gh, workflow) in &told {
        assert!(gh.contains("`gh.allow` ([\"pr view\"])"), "{cell}: {gh}");
        for copied in ["pr list", "repo view", "release view", "search"] {
            assert!(!gh.contains(copied), "{cell}: {copied}: {gh}");
        }
        assert!(workflow.contains("`project.ci.measure` (none)"), "{cell}: {workflow}");
    }
    // The installation allows more, and the project lists a workflow.
    let install = std::fs::read_to_string(s.data.join("install.toml")).unwrap();
    write(
        &s.data,
        "install.toml",
        &install.replace("allow = [\"pr view\"]", "allow = [\"pr view\", \"run list\"]"),
    );
    lists_a_measurement_workflow(&s);
    for (cell, gh, workflow) in &tool_descriptions(&s) {
        assert!(gh.contains("`gh.allow` ([\"pr view\",\"run list\"])"), "{cell}: {gh}");
        assert!(
            workflow.contains(
                "`project.ci.measure` ([{\"workflow\":\"measure.yml\",\"inputs\":[\"command\",\"base\"],\
                 \"artifact\":\"measurement\"}])"
            ),
            "{cell}: {workflow}"
        );
    }
    let _ = std::fs::remove_dir_all(&s.root);
}

// A message the service refused is not run again in the session that holds what it refused: the line's session ends
// and the round runs once more in a new one.
#[test]
fn a_refused_run_goes_on_in_a_new_session_and_pauses_when_refused_again() {
    let report =
        "API Error: Opus 5.5's safeguards flagged this message (https://www.anthropic.com/legal/aup).".to_string();
    let (s, mut e, said, item) = failing("flagged-once", report.clone(), 1);
    for _ in 0..6 {
        e.tick().unwrap();
        if state(&e, item).unwrap().1 != "R1" {
            break;
        }
    }
    let log = said.lock().unwrap().join("\n");
    let (work, at, paused) = state(&e, item).unwrap();
    assert_eq!(paused, None, "{log}");
    assert_ne!(at, "R1", "{log}");
    assert_eq!(failed_kinds(&e), ["flagged"]);
    let sessions: Vec<(i64, Option<i64>)> = {
        let conn = e.db.conn();
        let mut st = conn
            .prepare(
                "SELECT r.session, s.ended FROM rounds r JOIN sessions s ON s.id = r.session
                 WHERE r.work = ?1 AND r.cell = 'R1' ORDER BY r.n",
            )
            .unwrap();
        st.query_map([work], |r| Ok((r.get(0)?, r.get(1)?)))
            .unwrap()
            .map(Result::unwrap)
            .collect()
    };
    assert_eq!(sessions.len(), 2, "{sessions:?}");
    assert_ne!(sessions[0].0, sessions[1].0, "{sessions:?}");
    assert!(sessions[0].1.is_some(), "{sessions:?}");
    let _ = std::fs::remove_dir_all(&s.root);
}

// Refused again in the new session, the work pauses and the owner is told, naming both rounds: what the agent is given
// needs a look.
#[test]
fn a_run_refused_twice_pauses_its_work() {
    let report =
        "API Error: Opus 5.5's safeguards flagged this message (https://www.anthropic.com/legal/aup).".to_string();
    let (s, mut e, said, item) = failing("flagged-twice", report, 2);
    for _ in 0..6 {
        e.tick().unwrap();
    }
    let log = said.lock().unwrap().join("\n");
    let (_, at, paused) = state(&e, item).unwrap();
    assert_eq!(at, "R1", "{log}");
    assert!(
        paused.as_deref().is_some_and(|p| p.contains("refused the agent's run")),
        "{paused:?}\n{log}"
    );
    assert_eq!(failed_kinds(&e), ["flagged", "flagged"]);
    let _ = std::fs::remove_dir_all(&s.root);
}

// A passing failure runs the same round again until it passes: the work neither pauses nor asks anyone, and none of
// it is a return sent back.
#[test]
fn a_passing_failure_runs_again_until_it_passes() {
    let (s, mut e, said, item) = failing("transient", "API Error: 529 Overloaded".to_string(), 3);
    for _ in 0..10 {
        e.tick().unwrap();
        if state(&e, item).unwrap().1 != "R1" {
            break;
        }
    }
    let log = said.lock().unwrap().join("\n");
    let (_, at, paused) = state(&e, item).unwrap();
    assert_ne!(at, "R1", "{log}");
    assert_eq!(paused, None, "{log}");
    assert_eq!(failed_kinds(&e), ["transient", "transient", "transient"]);
    assert_eq!(sent_back(&e), 0);
    // The round after a failed run is told its kind only, never what the command line reported, which may quote the
    // run's own return. The report is looked for whole: the test's directory holds its process id, which may hold 529.
    let (work, _, _) = state(&e, item).unwrap();
    // Each run again is a retry; none is a return sent back.
    assert_eq!((counted(&e, work, "retries"), counted(&e, work, "sent_back")), (3, 0));
    let again = message_at(&e, work, "R1", true);
    assert!(
        again.contains("ended without a return (transient)") && !again.contains("529 Overloaded"),
        "{again}"
    );
    // The session holds the message of the run that failed, which the command line wrote there: the round run again
    // is not given it once more.
    let first = message_at(&e, work, "R1", false);
    assert!(
        again.len() * 2 < first.len(),
        "{} of {}\n{again}",
        again.len(),
        first.len()
    );
    let _ = std::fs::remove_dir_all(&s.root);
}

/// A work whose cell `R1` breaks its first return as `fault` says, the script `@repair` answering a repair of it as
/// `repair` says, if given, and every later return of `R1` as `later` says, if given.
fn unparsed_at_r1(
    name: &str,
    fault: &'static str,
    repair: Option<Script>,
    later: Option<&'static str>,
) -> (Setup, Engine, Arc<Mutex<Vec<String>>>, i64) {
    let s = setup(name);
    let mut agents = scripts();
    agents.insert(
        "R1",
        Box::new(move |_: &Request, n: usize| match (n, later) {
            (1, _) => (Vec::new(), vec![("@unparsed", json!(fault))]),
            (_, Some(f)) => (Vec::new(), vec![("@unparsed", json!(f))]),
            _ => (Vec::new(), Vec::new()),
        }),
    );
    if let Some(r) = repair {
        agents.insert("@repair", r);
    }
    let (e, said, item) = start(&s, agents);
    (s, e, said, item)
}

/// What the record of a work's first round at `R1` keeps of the repair of its return, with its contents put back.
fn repair_record(e: &Engine, work: i64) -> (Value, Value) {
    let (input, usage): (String, Option<String>) =
        e.db.conn()
            .query_row(
                "SELECT input, usage FROM rounds WHERE work = ?1 AND cell = 'R1' ORDER BY n LIMIT 1",
                [work],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .unwrap();
    let input = db::put_back(e.db.conn(), &serde_json::from_str(&input).unwrap());
    let usage = usage.map(|u| serde_json::from_str(&u).unwrap()).unwrap_or(Value::Null);
    (input["engine"]["unparsed"].clone(), usage)
}

/// Takes steps until the work on the item has left `R1` or paused.
fn past_r1(e: &mut Engine, item: i64) {
    for _ in 0..6 {
        e.step(None).unwrap();
        if state(e, item).is_some_and(|(_, at, paused)| at != "R1" || paused.is_some()) {
            break;
        }
    }
}

// A return that lacks only its last brace, its fields every return holds written inside `outcome`, is closed by the
// engine within its round, with those fields moved up beside `outcome`: the round takes its row, nothing is run again,
// and no repair is asked of a model.
#[test]
fn a_return_that_lacks_only_its_last_brace_is_closed_within_its_round() {
    let (s, mut e, said, item) = unparsed_at_r1("unparsed-close", "drop_last_brace", None, None);
    past_r1(&mut e, item);
    let log = said.lock().unwrap().join("\n");
    let (work, at, paused) = state(&e, item).unwrap();
    assert_eq!((at.as_str(), paused), ("R2", None), "{log}");
    assert_eq!(rows_at(&e, work, "R1"), ["done"], "{log}");
    assert!(failed_kinds(&e).is_empty(), "{log}");
    let (record, _) = repair_record(&e, work);
    assert_eq!(record["closed"]["added"], "}", "{record}");
    assert!(
        record.get("repair").is_none() && record.get("again").is_none(),
        "{record}"
    );
    assert!(
        record["attempts"][0]["text"]
            .as_str()
            .is_some_and(|t| t.contains("\"tell_owner\"")),
        "{record}"
    );
    let _ = std::fs::remove_dir_all(&s.root);
}

/// What the first round of a work at `R1` records of a form taken from the JSON text of it: the field it was.
fn taken_from_text(e: &Engine, work: i64) -> Option<String> {
    e.db.conn()
        .query_row(
            "SELECT json_extract(input, '$.engine.taken_from_text') FROM rounds
             WHERE work = ?1 AND cell = 'R1' ORDER BY n LIMIT 1",
            [work],
            |r| r.get(0),
        )
        .unwrap()
}

// A return whose outcome the agent wrote as a string holding its JSON is taken with the outcome that JSON holds: the
// round takes its row, and records that its outcome was taken from the text.
#[test]
fn an_outcome_handed_in_as_its_json_text_is_taken_as_the_object() {
    let s = setup("outcome-text");
    let mut agents = scripts();
    agents.insert(
        "R1",
        Box::new(|_: &Request, n: usize| match n {
            1 => (Vec::new(), vec![("@outcome_text", json!(true))]),
            _ => (Vec::new(), Vec::new()),
        }),
    );
    let (mut e, said, item) = start(&s, agents);
    past_r1(&mut e, item);
    let log = said.lock().unwrap().join("\n");
    let (work, at, paused) = state(&e, item).unwrap();
    assert_eq!((at.as_str(), paused), ("R2", None), "{log}");
    assert_eq!(rows_at(&e, work, "R1"), ["done"], "{log}");
    assert_eq!(sent_back(&e), 0, "{log}");
    assert_eq!(taken_from_text(&e, work).as_deref(), Some("outcome"), "{log}");
    let _ = std::fs::remove_dir_all(&s.root);
}

/// What the first round of a work at `R1` keeps under `engine` in its record.
fn engine_record(e: &Engine, work: i64) -> Value {
    let text: String =
        e.db.conn()
            .query_row(
                "SELECT json_extract(input, '$.engine') FROM rounds WHERE work = ?1 AND cell = 'R1'
                 ORDER BY n LIMIT 1",
                [work],
                |r| r.get(0),
            )
            .unwrap();
    serde_json::from_str(&text).unwrap()
}

// A round records where its return was read from: the tool's input, which the command line checked, or the text of the
// run's result, which no check of it saw. A null a return holds in a field of another form than its own (`ask` beside
// the understanding) is taken as left out, the round takes its row with nothing sent back, and the round records the
// path of the null; a return with no such null records none.
#[test]
fn a_round_records_where_its_return_came_from_and_the_nulls_it_took_as_left_out() {
    for (from, nulls) in [("text", true), ("tool", false)] {
        let s = setup(&format!("return-from-{from}"));
        let mut agents = scripts();
        agents.insert(
            "R1",
            Box::new(move |_: &Request, n: usize| match n {
                1 if nulls => (
                    Vec::new(),
                    vec![("@from", json!(from)), ("@foreign_null", json!("ask"))],
                ),
                1 => (Vec::new(), vec![("@from", json!(from))]),
                _ => (Vec::new(), Vec::new()),
            }),
        );
        let (mut e, said, item) = start(&s, agents);
        past_r1(&mut e, item);
        let log = said.lock().unwrap().join("\n");
        let (work, at, paused) = state(&e, item).unwrap();
        assert_eq!((at.as_str(), paused), ("R2", None), "{log}");
        assert_eq!(rows_at(&e, work, "R1"), ["done"], "{log}");
        assert_eq!(sent_back(&e), 0, "{log}");
        let record = engine_record(&e, work);
        assert_eq!(record["return_from"], from, "{record}");
        assert_eq!(
            record.get("foreign_nulls").cloned(),
            nulls.then(|| json!(["outcome.ask"])),
            "{record}"
        );
        let _ = std::fs::remove_dir_all(&s.root);
    }
}

// A run the command line gave up on because its last attempt held the outcome as a string of its JSON is taken from
// that attempt within its round, with the outcome its JSON holds: nothing is repaired or handed in again, and the
// round records both the attempt and that its outcome was taken from the text.
